// One notice for the assistant with the new emails: sender, subject and id. No body: the assistant reads the
// email itself with its Gmail connector, so nothing from the email is typed into its terminal but these two lines.
function decodeWords(s) { // =?UTF-8?B?...?= / =?UTF-8?Q?...?= subjects
  s = String(s || '');
  try {
    return s.replace(/=\?([^?]+)\?([BbQq])\?([^?]*)\?=/g, (m, cs, enc, t) => {
      const buf = /b/i.test(enc) ? Buffer.from(t, 'base64')
        : Buffer.from(t.replace(/_/g, ' ').replace(/=([0-9A-Fa-f]{2})/g, (x, h) => String.fromCharCode(parseInt(h, 16))), 'binary');
      return buf.toString(/utf-?8/i.test(cs) ? 'utf8' : 'latin1');
    }).replace(/\?=\s+=\?/g, '');
  } catch (e) { return s; }
}
const short = (s, n) => { s = decodeWords(s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; };
const MAX_AGE_HOURS = 3;   // the first search after activation can return the day's older unread emails: skip them
const mem = $getWorkflowStaticData('global');
mem.seen = mem.seen || [];
const now = Date.now();
const lines = [];
for (const item of $input.all()) {
  const j = item.json, meta = j.metadata || {};
  const id = String(meta['message-id'] || meta['Message-ID'] || j.attributes?.uid || '').trim();
  if (id && mem.seen.includes(id)) continue;
  const date = Date.parse(j.date || meta.date || '');
  if (!isNaN(date) && now - date > MAX_AGE_HOURS * 3600 * 1000) continue;
  if (id) mem.seen.push(id);
  lines.push('From: ' + short(j.from, 120) + ' · Subject: "' + short(j.subject || '(no subject)', 160) + '"' +
             (id ? ' · rfc822msgid:' + id.replace(/[<>]/g, '') : ''));
}
mem.seen = mem.seen.slice(-300);
if (!lines.length) return [];
return [{ json: { source: 'email', text: (lines.length === 1 ? 'New email in the inbox: ' : lines.length + ' new emails in the inbox: ') + lines.join(' ‖ ') } }];
